svg.script:
if (!svg_circle) {
  const svg_circle = document.querySelectorAll(".svg_circle");

  svg_circle.forEach( svg => {
      svg.addEventListener("click", (event) => {
        const svg_circleColor = event.target.getAttribute("stroke");

        if ( event.target.getAttribute("fill") === "transparent") {
            event.target.setAttribute("fill", svg_circleColor);
        } else {
            event.target.setAttribute("fill", "transparent");
        }
    });
  });
}
